"""Australia: mapped sites. Coordinates from OSM Nominatim / Wikipedia lookups (Oct 2026); approx where only road or locality matched."""
import sys
sys.path.insert(0, "/home/claude/winesite/scripts/c12")
from c12_common import site

S = []


def s(*a, **k):
    S.append(site("au", *a, **k))


# Barossa and Eden Valley
s("Langmeil Freedom 1843 Vineyard", "vineyard", -34.5082, 138.9637, "Langmeil's winery on the North Para River at Tanunda stands beside the Freedom vineyard, a block of Shiraz planted in 1843 by Christian Auricht, a Silesian settler. It is generally cited as the oldest continuously producing Shiraz vineyard in the world. The Lindner family bought the site in 1996, and the wine, Freedom 1843 Shiraz, comes from about 3.5 acres of gnarled, own-rooted vines.", appellation="Barossa Valley", cls="Ancestor vines (Barossa Old Vine Charter)", producers=["Langmeil"])
s("Turkey Flat", "estate", -34.5354, 138.9609, "The Schulz family's Turkey Flat at Bethany, on the southern edge of Tanunda, holds Shiraz planted in 1847 by Johann Fiedler, a Silesian settler, among the oldest vines in the Barossa. The cellar door is in the old butcher's shop and bluestone cottage. Turkey Flat also helped revive Barossa Grenache and Mataro rosé.", appellation="Barossa Valley", producers=["Turkey Flat"], q="approx")
s("Seppeltsfield", "estate", -34.4892, 138.9184, "Joseph Seppelt, a Silesian snuff and tobacco merchant, bought land here in 1851 and built a wine village of bluestone cellars. In 1878 his son Benno laid down a barrel of Tawny to be opened in 1978, beginning the Centennial Collection, the world's only unbroken run of single-vintage Tawny since 1878. Each year the 100-year-old Para Vintage Tawny is released (the 1926 in 2026), in 100 ml bottles.", appellation="Barossa Valley", cls="Centennial Collection, 100 Year Old Para Vintage Tawny", producers=["Seppeltsfield"])
s("Seppelt Family Mausoleum", "historic", -34.4863, 138.9277, "A Doric-columned mausoleum built in 1927 on a hill above Seppeltsfield, reached along an avenue of about 2,000 date palms planted by Seppelt workers during the Depression of the 1930s. It is one of the most photographed landmarks in Australian wine.", appellation="Barossa Valley", producers=["Seppeltsfield"])
s("Yalumba", "estate", -34.5133, 139.0551, "Founded in 1849 at Angaston by Samuel Smith, an English brewer, Yalumba is Australia's oldest family-owned winery, now run by the fifth generation of the Hill-Smith family. Its blue-marble clock-tower winery dates from 1908, and it is one of the few Australian wineries with its own cooperage. Yalumba drafted the Barossa Old Vine Charter in 2007 and planted Viognier in the Eden Valley in 1980, a pioneering move.", appellation="Barossa", producers=["Yalumba"])
s("Chateau Tanunda", "historic", -34.5279, 138.9643, "Built in 1890 from Bethany bluestone in eleven months, Chateau Tanunda was the largest building in the Southern Hemisphere when finished, a co-operative winery and distillery designed to exploit Europe's phylloxera shortage. Seppelt owned it from 1916 to 1998; the Geber family restored it and its cellars, and it is on the South Australian Heritage Register.", appellation="Barossa Valley", producers=["Chateau Tanunda"])
s("Rockford", "estate", -34.557, 138.961, "Robert O'Callaghan's Rockford, founded in 1984 in old stone buildings at Krondorf, became the conscience of the Barossa during the 1980s vine-pull years by buying old-vine fruit from growers and making it with 1880s machinery, including a hand-fed basket press. Its Basket Press Shiraz and cellar-door-only Black Shiraz (a sparkling red) are cult wines.", appellation="Barossa Valley", producers=["Rockford"])
s("Torbreck", "estate", -34.48, 138.942, "Founded by David Powell in 1994 at Marananga, in the northern-central Barossa, Torbreck built its reputation on old-vine Shiraz, Grenache and Mataro sourced from family growers, and on Rhône-inspired blends such as RunRig (Shiraz with a little Viognier). It became one of the defining names of the 1990s and 2000s Barossa boom.", appellation="Barossa Valley", producers=["Torbreck"], q="approx")
s("Penfolds Kalimna (Block 42)", "vineyard", -34.4141, 138.9507, "Penfolds bought the Kalimna vineyard near Moppa in the northern Barossa in 1945. Its Block 42, planted around 1888, is thought to be the oldest continuously producing Cabernet Sauvignon vineyard in the world, and is bottled separately only in rare years. Kalimna fruit has been a backbone of Grange.", appellation="Barossa Valley", producers=["Penfolds"], q="approx")
s("Cirillo Old Vines, Light Pass", "vineyard", -34.471, 139.0299, "The Cirillo family's Grenache at Light Pass was planted in 1848 on deep sand and still grows on its own roots; it is among the oldest Grenache vines in the world. The family bought the vineyard in 1969, and the wine is named The Vincent after Vincenzo Cirillo.", appellation="Barossa Valley", producers=["Cirillo Estate"], q="approx")
s("Hewitson Old Garden, Rowland Flat", "vineyard", -34.5709, 138.9284, "A block of Mourvèdre at Rowland Flat planted in 1853, said to be the oldest Mourvèdre vines in the world. Dean Hewitson bought it in 1998 and has propagated cuttings from it, partly to safeguard the genetic material.", appellation="Barossa Valley", producers=["Hewitson"], q="approx")
s("Jacob's Creek Visitor Centre", "estate", -34.5647, 138.9333, "Johann Gramp planted the first commercial vineyard in the Barossa beside Jacob's Creek at Rowland Flat in 1847. His company, Orlando, made the first Jacob's Creek red from the 1973 vintage and turned it into one of the best-known Australian wines abroad.", appellation="Barossa Valley", producers=["Jacob's Creek"])
s("Peter Lehmann Wines", "estate", -34.5063, 138.9677, "When an oversupply in the late 1970s left Barossa growers with no buyer, Peter Lehmann, then winemaker at Saltram, kept buying their grapes and founded his own company in 1979. His guarantee helped save many old vineyards from the government-funded vine pull of the 1980s.", appellation="Barossa Valley", producers=["Peter Lehmann"])
s("Henschke, Keyneton", "estate", -34.5208, 139.1508, "Johann Christian Henschke, a Silesian stonemason, began making wine at Keyneton in 1868, and the family's sixth generation now runs it. Cyril Henschke released Hill of Grace as a single-vineyard wine with the 1958 vintage, and Stephen and Prue Henschke turned the estate into a leader of sustainable and biodynamic viticulture.", appellation="Eden Valley", producers=["Henschke"])
s("Hill of Grace", "vineyard", -34.499, 139.129, "An eight-hectare vineyard opposite the Gnadenberg (Hill of Grace) Lutheran church near Moculta, planted by Nicolaus Stanitzki in the 1860s. Its oldest Shiraz vines, the 'Grandfathers', are around 160 years old and still own-rooted. Hill of Grace Shiraz is Australia's most famous single-vineyard wine after Grange.", appellation="Eden Valley", cls="Single vineyard, Ancestor vines", producers=["Henschke"], q="approx")
s("Mount Edelstone", "vineyard", -34.56, 139.115, "A 16-hectare Shiraz vineyard near Keyneton, planted in 1912 by Ronald Angas and bought by Cyril Henschke in 1974. Its wine, first made as a single vineyard in 1952, is one of Australia's longest-running single-vineyard Shiraz labels.", appellation="Eden Valley", producers=["Henschke"], q="approx")
s("Pewsey Vale", "vineyard", -34.6369, 138.9702, "Joseph Gilbert planted Pewsey Vale in the High Eden hills in 1847. Yalumba replanted it in 1961 after decades of grazing, and its terraced Riesling vineyard, at nearly 500 m, now produces The Contours, a Riesling released with five years in bottle.", appellation="Eden Valley", producers=["Pewsey Vale", "Yalumba"], q="approx")

# Clare
s("Grosset, Auburn", "estate", -34.0267, 138.6903, "Jeffrey Grosset opened his winery in a former dairy factory in Auburn in 1981. He led the 2000 Clare Valley screwcap initiative and makes two benchmark Rieslings that show the region's split: Polish Hill (slate, austere) and Springvale (red loam over limestone at Watervale).", appellation="Clare Valley", producers=["Grosset"], q="approx")
s("Polish Hill River", "village", -33.8859, 138.6882, "A side valley east of Sevenhill settled by Polish immigrants from 1856, whose stone church of St Stanislaus Kostka (1871) is now a museum. The valley's hard slate and shale soils produce the leanest, most mineral Clare Rieslings, including Grosset's Polish Hill, first made in 1981.", appellation="Clare Valley", producers=["Grosset", "Paulett", "Pikes"], q="approx")
s("Sevenhill Cellars", "historic", -33.888, 138.634, "Austrian Jesuits fleeing persecution founded Sevenhill in 1851 and planted vines to make sacramental wine. It is the oldest winery in the Clare Valley and still run by the Jesuits, with St Aloysius' church (1875) and a crypt beneath it on the property.", appellation="Clare Valley", producers=["Sevenhill Cellars"], q="approx")
s("Wendouree", "estate", -33.8559, 138.6222, "A winery founded in 1895 near Clare whose old, dry-grown Shiraz, Malbec, Cabernet and Mataro are made by Tony Brady and family in the same slate-walled cellar. Wendouree sells almost entirely by mailing list, has no cellar door or website, and its tannic reds need two decades.", appellation="Clare Valley", producers=["Wendouree"], q="approx")
s("Jim Barry Wines", "estate", -33.8183, 138.5974, "Jim Barry, the first qualified winemaker to work in the Clare Valley (1947), founded this company in 1959. The Armagh Shiraz, first made in 1985, is its flagship, and in 2016 it released Australia's first commercial Assyrtiko, from cuttings imported from Santorini.", appellation="Clare Valley", producers=["Jim Barry"])
s("Kilikanoon", "estate", -33.919, 138.6238, "A Clare producer founded at Penwortham in 1997, whose old-vine Shiraz (Oracle, Attunga 1865 from vines planted in 1865) and Mort's Block Riesling from Watervale are regional benchmarks. Its cellar door sits in a stone building among the vines in the centre of the valley.", appellation="Clare Valley", producers=["Kilikanoon"])

# McLaren Vale and Fleurieu
s("d'Arenberg Cube", "estate", -35.1971, 138.5516, "A five-storey glass building opened in 2017 at d'Arenberg, McLaren Vale, inspired by a Rubik's cube and designed to look as if it is floating above the vines. d'Arenberg was founded by Joseph Osborn in 1912 and is run by Chester Osborn, who still foot-treads and basket-presses reds. The Dead Arm Shiraz is named after a vine disease (Eutypa) that kills one arm of the vine.", appellation="McLaren Vale", producers=["d'Arenberg"])
s("Clarendon Hills Astralis", "vineyard", -35.115, 138.625, "Roman Bratasiuk's Clarendon Hills sources from old, dry-grown vines in the hills above Clarendon, at the northern edge of McLaren Vale. Astralis Shiraz, first made in 1994 from vines planted in the 1920s, became one of Australia's most expensive wines; the estate also bottles single-vineyard Grenache such as Romas and Blewitt Springs.", appellation="McLaren Vale", producers=["Clarendon Hills"], q="approx")
s("Hardys Tintara", "estate", -35.2328, 138.5513, "Thomas Hardy, who arrived in South Australia in 1850, bought the Tintara winery in McLaren Vale in 1876 and built the company that became Australia's largest. The old Tintara cellars on the main road still house a cellar door; the Hardy family's vineyards include Sauvignon Blanc planted in the 1870s.", appellation="McLaren Vale", producers=["Hardys"], q="approx")
s("Chateau Reynella", "historic", -35.093, 138.534, "John Reynell planted vines here in 1838, two years after South Australia was founded, and dug an underground cellar in 1845, one of the first winery buildings in the state. The property, now the headquarters of the Hardys business, holds the Old Cave Cellar.", appellation="McLaren Vale", producers=["Hardys", "Reynella"], q="approx")
s("Wirra Wirra", "estate", -35.2261, 138.5677, "Founded in 1894 by Robert Strangways Wigley, a cricket-loving eccentric, and revived in 1969 by Greg and Roger Trott. Its ironstone-walled winery and flagship RSW Shiraz and Church Block blend are McLaren Vale fixtures.", appellation="McLaren Vale", producers=["Wirra Wirra"])
s("Coriole", "estate", -35.1795, 138.5534, "The Lloyd family's Coriole, around an 1860 stone farmhouse, planted Sangiovese in 1985 and Fiano in 2000, early moves that helped make McLaren Vale Australia's laboratory for Mediterranean varieties.", appellation="McLaren Vale", producers=["Coriole"], q="approx")
s("Bleasdale", "estate", -35.3069, 139.0472, "Frank Potts founded Bleasdale at Langhorne Creek in 1850 and the family still runs it. Its red gum lever press, built in 1892 from a single tree, worked until 1960; Potts also flooded the vineyards in winter by diverting the Bremer River.", appellation="Langhorne Creek", producers=["Bleasdale"])
s("Shaw + Smith", "estate", -35.0055, 138.8231, "Founded in 1989 by Michael Hill Smith, Australia's first Master of Wine, and his cousin Martin Shaw. Their Adelaide Hills Sauvignon Blanc became a national benchmark; their M3 Chardonnay and Shiraz followed, and in 2011 they bought Tolpuddle in Tasmania.", appellation="Adelaide Hills", producers=["Shaw + Smith"])

# Adelaide
s("Penfolds Magill Estate", "historic", -34.921, 138.6791, "Dr Christopher Rawson Penfold and his wife Mary planted vines at their cottage, The Grange, in 1844. Max Schubert made the first experimental Grange Hermitage here in 1951. Penfolds still makes the Magill Estate Shiraz from the five-hectare suburban vineyard, one of the few urban single-vineyard wines in the world, and the restored Grange cottage is on site.", appellation="Adelaide", cls="Birthplace of Penfolds Grange", producers=["Penfolds"])

# Limestone Coast
s("Wynns Coonawarra Estate", "estate", -37.2931, 140.8297, "John Riddoch built this triple-gabled limestone winery in 1891 for his Penola Fruit Colony. The Wynn family bought it in 1951; its gabled facade, drawn by artist Richard Beck, became the emblem of Coonawarra on every Wynns label. It makes the Black Label Cabernet (from 1954) and the John Riddoch Cabernet (from 1982).", appellation="Coonawarra", producers=["Wynns Coonawarra Estate"])
s("Yallum Park", "historic", -37.3948, 140.75, "John Riddoch's homestead near Penola, built in 1880 for the pastoralist who founded the Coonawarra fruit colony in 1890. The Riddochs held huge pastoral runs across the south-east; Yallum Park is now a private heritage house.", appellation="Limestone Coast")
s("Majella", "estate", -37.3208, 140.8498, "The Lynn family were Coonawarra sheep farmers who planted vines in 1968 and sold grapes to Wynns before making their own wine from 1991. Majella's The Malleea Cabernet Shiraz is a classic Coonawarra blend.", appellation="Coonawarra", producers=["Majella"])

# Victoria
s("Tahbilk", "estate", -36.8196, 145.0873, "Founded in 1860 on the Goulburn River and owned by the Purbrick family since 1925, Tahbilk is the oldest family-owned winery in Victoria. A small block of Shiraz planted in 1860 survived phylloxera on its sandy soils and makes the 1860 Vines Shiraz; the estate also has one of the world's oldest and largest plantings of Marsanne (from 1927). Its 1860 cellars and tower are classified by the National Trust.", appellation="Nagambie Lakes", producers=["Tahbilk"])
s("Mitchelton", "estate", -36.8494, 145.09, "Founded in 1969 on the Goulburn River near Nagambie, with a 55-metre observation tower that is a local landmark; Mitchelton helped revive Marsanne and Rhône varieties in Victoria.", appellation="Nagambie Lakes", producers=["Mitchelton"])
s("Best's Great Western, Concongella", "vineyard", -37.1342, 142.84, "Henry Best planted Concongella in 1866, and the Thomson family has owned it since 1920. Its Nursery Block, planted in the 1860s, holds about 40 varieties, some still unidentified, and the world's oldest Pinot Meunier and Dolcetto vines; the 1868 slab-and-timber cellars are still in use.", appellation="Great Western", cls="Nursery Block (1860s)", producers=["Best's"])
s("Seppelt Great Western drives", "cellar", -37.1585, 142.8553, "Miners dug about 3 km of tunnels, called 'drives', into the hillside at Great Western from 1868 for Hans Irvine, who made traditional-method sparkling wine here. Seppelt bought the business in 1918 and used the drives to age 'Great Western' sparkling and the famous sparkling Shiraz. The drives are National Trust classified.", appellation="Great Western", producers=["Seppelt"])
s("Chambers Rosewood", "estate", -36.0446, 146.4508, "The Chambers family has made fortified wine at Rutherglen since 1858. Its Rare Muscat and Rare Muscadelle are blended from soleras that include wine laid down in the 1890s, and are among the most acclaimed fortified wines in the world. The cellar door is a working shed.", appellation="Rutherglen", cls="Rare Rutherglen Muscat", producers=["Chambers Rosewood"])
s("Morris", "estate", -36.0302, 146.613, "The Morris family has made wine near Rutherglen since George Francis Morris planted in 1859; by the 1880s his Fairfield winery was said to be one of the largest in the Southern Hemisphere. Mick and David Morris built its reputation for Muscat and Topaque; Old Premium Rare Muscat is the flagship.", appellation="Rutherglen", producers=["Morris"])
s("Campbells", "estate", -36.06, 146.431, "John Campbell, a Scottish gold miner, planted vines at Bobbie Burns in 1870, and the family still owns the winery. Campbells makes Muscat and Topaque on the four-tier Rutherglen ladder, with Merchant Prince Rare Muscat at the top, and Bobbie Burns Shiraz.", appellation="Rutherglen", producers=["Campbells"])
s("All Saints Estate", "estate", -35.9935, 146.4098, "A turreted red-brick castle at Wahgunyah built in 1880s style by George Sutherland Smith, a Scottish carpenter, modelled on the Castle of Mey. The estate has made fortified wine since 1864 and is now owned by the Brown family (Eileen Brown and her children).", appellation="Rutherglen", producers=["All Saints Estate"])
s("Brown Brothers, Milawa", "estate", -36.4538, 146.424, "John Francis Brown made his first wine at Milawa in 1889, and the family still runs one of Australia's largest family wineries. Brown Brothers pioneered variety trials in its Kindergarten winery and helped popularise Moscato and Prosecco in Australia.", appellation="King Valley", producers=["Brown Brothers"])
s("Giaconda", "estate", -36.3816, 146.5932, "Rick Kinzbrunner planted Giaconda on a steep granite slope at Everton Upper in 1982. Its Chardonnay, wild-fermented and aged in a cellar blasted into the granite, is one of Australia's most sought-after whites; production is tiny.", appellation="Beechworth", producers=["Giaconda"], q="approx")
s("Bass Phillip", "estate", -38.5582, 145.8799, "Phillip Jones planted close-spaced, unirrigated Pinot Noir at Leongatha South in 1979 on deep red soil and made wines compared with Burgundy. Burgundian Jean-Marie Fourrier and partners bought the estate in 2020.", appellation="Gippsland", producers=["Bass Phillip"])
s("Mount Mary", "estate", -37.744, 145.364, "Dr John Middleton, a Melbourne physician, planted Mount Mary at Lilydale in 1971. Its Quintet (all five Bordeaux red varieties) and Triolet (Sauvignon Blanc, Semillon, Muscadelle) are among Australia's most elegant wines, sold mostly by mailing list.", appellation="Yarra Valley", producers=["Mount Mary"], q="approx")
s("Yarra Yering", "estate", -37.7135, 145.467, "Dr Bailey Carrodus, a plant physiologist, planted Yarra Yering on a north-facing slope at Gruyere in 1969. His Dry Red No. 1 (Cabernet blend) and Dry Red No. 2 (Shiraz blend) were unlike anything else in Australia; Sarah Crowe has made the wines since 2013.", appellation="Yarra Valley", producers=["Yarra Yering"])
s("Yeringberg", "estate", -37.6901, 145.4346, "Guillaume de Pury, a Swiss from Neuchâtel, founded Yeringberg in 1863, and his descendants still own it. Wine stopped in 1921 and resumed in 1969 in the original 1885 three-storey gravity winery.", appellation="Yarra Valley", producers=["Yeringberg"])
s("Domaine Chandon Australia", "estate", -37.6797, 145.4302, "Moët & Chandon's Australian outpost, founded at Coldstream in 1986 on the old Green Point farm, helped prove that the Yarra Valley could make serious traditional-method sparkling wine.", appellation="Yarra Valley", producers=["Chandon"])
s("De Bortoli Yarra Valley", "estate", -37.5981, 145.4109, "The Riverina's De Bortoli family bought a Dixons Creek vineyard in 1987, and Steve Webber and Leanne De Bortoli turned it into a leader of lighter, more transparent Yarra Pinot Noir and Chardonnay.", appellation="Yarra Valley", producers=["De Bortoli"])
s("Paringa Estate", "estate", -38.3878, 145.0382, "Lindsay McCall, a schoolteacher, planted Paringa at Red Hill South in 1985; its Pinot Noir and Shiraz won national trophies and put the Mornington Peninsula on the map.", appellation="Mornington Peninsula", producers=["Paringa Estate"])
s("Ten Minutes by Tractor", "estate", -38.3947, 144.9946, "Named after the time it takes to drive a tractor between its original three vineyards, this Mornington Peninsula producer makes single-vineyard Pinot and Chardonnay that show the peninsula's site differences.", appellation="Mornington Peninsula", producers=["Ten Minutes by Tractor"])
s("Bannockburn Vineyards", "estate", -38.0422, 144.198, "Stuart Hooper planted Bannockburn in the Moorabool Valley in 1974; Gary Farr, its winemaker for 20 years, worked vintages at Domaine Dujac. The close-planted Serré Pinot Noir is its icon.", appellation="Geelong", producers=["Bannockburn"])
s("Jasper Hill", "estate", -36.854, 144.685, "Ron and Elva Laughton planted Jasper Hill on Heathcote's Cambrian greenstone in 1975, dry-grown and own-rooted. Georgia's Paddock and Emily's Paddock Shiraz made the region's reputation.", appellation="Heathcote", producers=["Jasper Hill"], q="approx")
s("Balgownie Estate, Bendigo", "estate", -36.7334, 144.1914, "Stuart Anderson, a pharmacist, planted Balgownie at Maiden Gully in 1969, reviving viticulture in Bendigo after phylloxera and government-ordered uprooting had ended it about 70 years earlier. Its Shiraz and Cabernet, firm and minty, made Bendigo a fine-wine name again.", appellation="Bendigo", producers=["Balgownie Estate"])
s("Dalwhinnie", "estate", -36.969, 143.2505, "A Pyrenees estate at Moonambel planted in 1976 in an amphitheatre of hills, known for structured, long-lived Shiraz and Cabernet from dry-grown vines on quartz gravel at around 500 to 600 m. It is one of the region's most consistent producers.", appellation="Pyrenees", producers=["Dalwhinnie"])

# NSW
s("Farm Cove", "historic", -33.8607, 151.2191, "The first vines in Australia were planted at Farm Cove on Sydney Harbour in 1788, from cuttings the First Fleet collected at Rio de Janeiro and the Cape. They failed in the humid climate; the site is now part of the Royal Botanic Garden.", appellation="New South Wales")
s("Elizabeth Farm", "historic", -33.8212, 151.018, "John and Elizabeth Macarthur's farmhouse at Parramatta (1793), the oldest surviving European building in Australia. The Macarthurs' sons later planted vines at Camden Park and sent wine to London; Elizabeth Farm is now a museum.", appellation="New South Wales")
s("Dalwood Estate", "historic", -32.6447, 151.4214, "George Wyndham planted vines at Dalwood on the Hunter River in 1828, among the first in the valley. Penfolds later owned it; it is now a small estate again.", appellation="Hunter")
s("Tyrrell's", "estate", -32.7728, 151.2726, "Edward Tyrrell planted at Ashmans in 1858, and the family's fifth generation runs it. Vat 1 Semillon is the archetypal Hunter Semillon; Vat 47 (1971) was Australia's first commercial varietal Chardonnay, and the Old Patch Shiraz vines date from 1867.", appellation="Pokolbin", producers=["Tyrrell's"])
s("Mount Pleasant", "estate", -32.8182, 151.2857, "Maurice O'Shea, trained in France, made wine at Mount Pleasant from 1921 until his death in 1956, and his medium-bodied 'Hunter Burgundy' reds and Semillons are legendary. McWilliam's took full control in 1941, and the estate passed to new private owners in 2021 when McWilliam's was sold up; vines planted in 1880 and 1921 still crop.", appellation="Pokolbin", producers=["Mount Pleasant"])
s("Lake's Folly", "estate", -32.7774, 151.3325, "Dr Max Lake, a Sydney surgeon, planted Cabernet Sauvignon at Pokolbin in 1963, the first new vineyard in the Hunter for decades and the start of Australia's boutique winery movement.", appellation="Pokolbin", producers=["Lake's Folly"])
s("Clonakilla", "estate", -34.9908, 149.0346, "CSIRO scientist John Kirk planted Clonakilla at Murrumbateman in 1971. His son Tim, inspired by Côte-Rôtie, co-fermented Shiraz with a little Viognier from 1992, creating one of Australia's most influential wines.", appellation="Canberra District", producers=["Clonakilla"])
s("Helm Wines", "estate", -34.9691, 149.087, "Ken Helm, descended from German vignerons, founded Helm at Murrumbateman in 1973 in a nineteenth-century schoolhouse. He champions dry Riesling, founded the Canberra International Riesling Challenge in 2000, and helped make the Canberra District one of Australia's Riesling regions.", appellation="Canberra District", producers=["Helm"])
s("Philip Shaw", "estate", -33.3122, 149.0791, "Former Rosemount chief winemaker Philip Shaw planted the Koomooloo vineyard on the slopes of Mount Canobolas in 1989, at about 900 m on volcanic soils. His Chardonnay and Shiraz helped build Orange's cool-climate reputation, and his sons now run the estate.", appellation="Orange", producers=["Philip Shaw"])

# WA
s("Vasse Felix", "estate", -33.8225, 115.0375, "Dr Tom Cullity, a Perth cardiologist, planted Margaret River's first commercial vineyard here in 1967 after reading John Gladstones' climate research. Vasse Felix is now known for its Heytesbury Chardonnay and Tom Cullity Cabernet.", appellation="Margaret River", producers=["Vasse Felix"])
s("Moss Wood", "estate", -33.7844, 115.0358, "Dr Bill Pannell planted Moss Wood at Wilyabrup in 1969; Keith and Clare Mugford have owned it since 1985. Its Cabernet Sauvignon is one of Australia's most consistent and long-lived.", appellation="Margaret River", producers=["Moss Wood"])
s("Cullen Wines", "estate", -33.8192, 115.0375, "Kevin and Diana Cullen planted at Wilyabrup in 1971; their daughter Vanya made the estate biodynamic and carbon-neutral. The Diana Madeline Cabernet blend is a Margaret River benchmark.", appellation="Margaret River", producers=["Cullen"])
s("Leeuwin Estate", "estate", -34.0131, 115.0658, "Denis and Tricia Horgan founded Leeuwin in 1974 with advice from Robert Mondavi. Its Art Series Chardonnay, first made in 1980, is often called Australia's finest white wine; the estate's concerts on the lawn have run since 1985.", appellation="Margaret River", producers=["Leeuwin Estate"])
s("Voyager Estate", "estate", -33.9951, 115.0539, "A white Cape Dutch-style estate on Stevens Road, planted in 1978 and bought by mining magnate Michael Wright in 1991. Voyager is known for Chardonnay and Cabernet from the cooler southern part of Margaret River, and now farms organically.", appellation="Margaret River", producers=["Voyager Estate"])
s("Houghton", "historic", -31.8542, 115.9989, "Founded in 1836 in the Swan Valley and named after Colonel Richard Houghton, one of the original partners. Jack Mann, winemaker from 1930 to 1972, created Houghton White Burgundy (1937), Australia's best-selling white for decades.", appellation="Swan Valley", producers=["Houghton"])
s("Sandalford", "estate", -31.87, 115.9946, "John Septimus Roe, Western Australia's first Surveyor-General, was granted land on the Swan River in 1840; the family began making wine commercially here, and the estate's jetty still serves wine-cruise boats from Perth.", appellation="Swan Valley", producers=["Sandalford"], q="approx")
s("Frankland Estate", "estate", -34.4656, 117.0063, "Barrie Smith and Judi Cullam planted vines on their sheep farm at Frankland River in 1988; their Isolation Ridge Riesling and organic farming helped make the Great Southern a Riesling region.", appellation="Frankland River", producers=["Frankland Estate"])
s("Plantagenet", "estate", -34.63, 117.664, "Tony Smith, an English-born farmer, planted Plantagenet near Mount Barker in 1968, the first commercial winery in the Great Southern, in a former apple-packing shed.", appellation="Mount Barker", producers=["Plantagenet"], q="approx")
s("Castle Rock Estate", "estate", -34.6489, 117.8192, "Angelo and Wendy Diletti's vineyards on the north-facing granite slopes of the Porongurup Range were planted in 1981, above the frost line. Their delicate, mineral, long-lived Rieslings and fine Pinot Noir define the subregion's style.", appellation="Porongurup", producers=["Castle Rock Estate"], q="approx")

# Tasmania, Queensland
s("Stefano Lubiana", "estate", -42.7461, 147.2021, "Steve and Monique Lubiana moved from South Australia's Riverland to the Derwent Valley in 1990 and built a biodynamic estate making Pinot Noir, Chardonnay and long-aged sparkling.", appellation="Tasmania", producers=["Stefano Lubiana"])
s("Tolpuddle Vineyard", "vineyard", -42.763, 147.3864, "Planted in 1988 in the Coal River Valley near Richmond and named after the Tolpuddle Martyrs, one of whom was transported to Tasmania. Shaw + Smith bought it in 2011, and its Pinot Noir and Chardonnay are among Australia's best.", appellation="Tasmania", producers=["Tolpuddle"])
s("Josef Chromy", "estate", -41.5059, 147.205, "Josef Chromy fled Czechoslovakia in 1950, became a butcher in Launceston, and later invested in Tasmanian wine (Rochecombe, Jansz). His own estate at Relbia, in the Tamar Valley, opened in 2007.", appellation="Tasmania", producers=["Josef Chromy"])
s("Jansz", "estate", -41.0738, 147.196, "Founded in 1985 at Pipers River as a joint venture with Champagne Louis Roederer and now owned by Yalumba's Hill-Smith family, Jansz showed that Tasmania could make serious traditional-method sparkling wine.", appellation="Tasmania", producers=["Jansz"])
s("Ballandean Estate", "estate", -28.8136, 151.8142, "The Puglisi family's estate in the Granite Belt traces its vines to 1932, when Italian migrants grew grapes on the granite plateau near Stanthorpe; it is Queensland's oldest family-owned winery.", appellation="Granite Belt", producers=["Ballandean Estate"])
